import { Component, Element, Event, EventEmitter, h, Host, Listen, Method, Prop, State, Watch } from '@stencil/core';
import { FormDataEvent, FormSize, Severity } from '../../types';
import { AriaAttributes, extractAriaAttributes } from '../../utils/a11y-helper';

/**
 * @nativeEvent change  - dispatched when value has changed => 'event.target.value' delivers the current value
 * @nativeEvent invalid - dispatched when input is invalid => 'event.target.value' delivers the current value
 *
 * @slot description - named slot 'description', here is any HTML content allowed.
 * @slot label - named slot 'label', here is any HTML content allowed.
 */
@Component({
  tag: 'groupui-textarea',
  styleUrl: 'textarea.scss',
  shadow: {
    delegatesFocus: true,
  },
})
export class Textarea {
  /**
   * placeholder of the textarea
   */
  @Prop({ reflect: true }) readonly placeholder: string;

  /**
   * value of the textarea
   */
  @Prop({ reflect: true, mutable: true }) value: string;

  /**
   * determines whether maxlength should prevent input of any more characters (html default behavior)
   */
  @Prop({ reflect: true }) readonly htmlMaxlengthBehavior: boolean = false;

  /**
   * sets textarea to readonly
   */
  @Prop({ reflect: true }) readonly disabled: boolean;

  /**
   * name of the input element to support forms
   */
  @Prop({ reflect: true }) readonly name: string;

  /**
   * number of rows in the textarea
   */
  @Prop({ reflect: true }) readonly rows: number = 2;

  /**
   * number of max rows in the textarea
   */
  @Prop({ reflect: true }) readonly maxRows: number;

  /**
   * specifies that a textarea must be filled out before submitting the form
   */
  @Prop({ reflect: true }) readonly required: boolean = false;

  /**
   * a string with placeholder about count of available and used characters. Works only
   *  in combination with maxlength.
   * Possible values:
   *  {characters-used}
   *  {characters-left}
   *  {characters-max}
   * e.g.:
   *    '{characters-used} characters used'
   *    '{characters-left} characters left'
   *    '{characters-used}/{characters-max}'
   */
  @Prop({ reflect: true }) readonly typingInfoTemplate: string;

  /**
   * When set to true, the typing information is always displayed. When set to false, it's only shown when the textarea has focus.
   */
  @Prop({ reflect: true }) readonly alwaysShowTypingInfo: boolean = false;

  /**
   * Aligns the typing info to the bottom left or bottom right side of the input. Won't have any effect, if a description is provided.
   */
  @Prop({ reflect: true }) readonly alignTypingInfo: 'left' | 'right' = 'left';

  /**
   * specifies that a textarea will grow in height if content would normally overflow
   */
  @Prop({ reflect: true }) readonly autoExpand: boolean = false;

  /**
   * sets the maximum amount of characters of the textarea
   */
  @Prop({ reflect: true }) readonly maxlength: number;

  /**
   * severity of the textarea component
   */
  @Prop({ reflect: true, mutable: true }) severity: Severity = 'none';

  /**
   * deactivate internal validations
   */
  @Prop({ reflect: true }) readonly noValidation: boolean;

  /**
   * in what way the textarea component is able to be resized
   */
  @Prop({ reflect: true }) readonly resize: 'none' | 'both' | 'vertical' | 'horizontal';

  /**
   * sets focus automatically
   */
  @Prop({ reflect: true }) readonly autofocus: boolean;

  /**
   * show status icon on severity danger, warning, success
   */
  @Prop({ reflect: true }) readonly showStatusIcon: boolean = false;

  /**
   * shows the description only when the component has focus
   */
  @Prop({ reflect: true }) readonly descriptionOnlyOnFocus: boolean = false;

  /**
   * toggles readonly mode
   */
  @Prop({ reflect: true }) readonly readonly: boolean;

  /**
   * returns the element's current validityState state (readonly value)
   */
  @Prop({ reflect: false, mutable: true }) validity: ValidityState;

  /**
   * sets the size of the textarea
   */
  @Prop({ reflect: true }) readonly size: FormSize = 'm';

  @Element() host: HTMLElement;

  /**
   * for react user only - use this instead of the native change event
   */
  @Event({ bubbles: false }) groupuiChange: EventEmitter<void>;

  /**
   * emits on input
   */
  @Event({ bubbles: false }) groupuiInput: EventEmitter<void>;

  /**
   * is dispatched when the value is invalid
   */
  @Event({ bubbles: false }) groupuiInvalid: EventEmitter<void>;

  /**
   * dispatched when component finished loading
   */
  @Event({ bubbles: false }) groupuiDidLoad: EventEmitter<void>;

  @State() hasFocus: boolean;

  @State() invalid: boolean;

  private ariaAttributes: AriaAttributes;

  @Watch('invalid')
  onInvalidChange() {
    this.validity = this.getValidity();
    if (this.invalid) {
      this.severity = 'danger';
      this.host.dispatchEvent(new window.Event('invalid'));
      this.groupuiInvalid.emit();
    } else {
      this.severity = null;
    }
  }

  @Listen('blur')
  onBlur() {
    this.hasFocus = false;
    this.validateTextarea();
  }

  @Listen('focus')
  onFocus() {
    this.hasFocus = true;
    this.host.shadowRoot.querySelector('textarea').focus();
  }

  @Listen('click')
  onClick(event) {
    if (this.disabled) {
      event.stopImmediatePropagation();
    } else {
      this.host.shadowRoot.querySelector('textarea').focus();
    }
  }

  /**
   * function to trigger component validation manually
   */
  @Method()
  async validate() {
    this.validateTextarea({ force: true });
  }

  componentWillLoad() {
    this.ariaAttributes = extractAriaAttributes(this.host);
    this.initFormsHandling();
  }

  componentDidLoad() {
    this.autofocus && this.host.focus && this.host.focus();
    this.validity = this.getValidity();
    this.groupuiDidLoad.emit();
  }

  componentDidRender() {
    this.expand();
  }

  private getValidity() {
    const tooLong = this.validateMax();
    const valueMissing = this.required && !this.value;
    return {
      valid: !tooLong && !valueMissing,
      tooLong,
      valueMissing,
      badInput: false,
      customError: false,
      patternMismatch: false,
      rangeOverflow: false,
      rangeUnderflow: false,
      stepMismatch: false,
      tooShort: false,
      typeMismatch: false,
    };
  }

  private initFormsHandling() {
    if (this.name === undefined) return;

    const form = this.host.closest('form');
    if (form == null) return;

    form.addEventListener('formdata', (event: FormDataEvent) => {
      event.formData.append(this.name, this.value);
    });

    form.addEventListener('submit', (event) => {
      this.validateTextarea();
      if (this.invalid) {
        event.preventDefault();
      }
    });
  }

  private validateTextarea = ({ force = false }: { force?: boolean } = {}) => {
    if (!force && this.noValidation) return;
    this.invalid = !this.getValidity().valid;
  };

  private validateMax() {
    return this.value?.length > this.maxlength;
  }

  private handleInput = (event) => {
    this.value = event.target.value;
    this.groupuiInput.emit();
  };

  private expand() {
    if (this.autoExpand) {
      this.updateDisplayedRows();
    }
  }

  private updateDisplayedRows() {
    this.resetDisplayedRows();
    const textarea = this.host.shadowRoot.querySelector('textarea');
    const rowCount = this.rowCount();
    textarea.style.height =
      this.lineHeight() * rowCount +
      this.paddingTop() +
      this.paddingBottom() +
      this.borderTopWidth() +
      this.borderBottomWidth() +
      'px';
  }

  private rowCount(): number {
    let result = this.fittingRowCount();
    if (this.rows) {
      result = Math.max(result, this.rows);
    }
    if (this.maxRows) {
      result = Math.min(result, this.maxRows);
    }
    return result;
  }

  private fittingRowCount(): number {
    const textarea = this.host.shadowRoot.querySelector('textarea');
    const scrollHeight = this.scrollHeight(textarea);
    const textHeight = scrollHeight - (this.paddingTop() + this.paddingBottom());

    return textHeight / this.lineHeight();
  }

  private scrollHeight(textarea: HTMLTextAreaElement): number {
    return textarea?.scrollHeight || 0;
  }

  private resetDisplayedRows() {
    const textarea = this.host.shadowRoot.querySelector('textarea');
    textarea.style.height =
      this.lineHeight() * this.numberOfRows() +
      this.paddingTop() +
      this.paddingBottom() +
      this.borderTopWidth() +
      this.borderBottomWidth() +
      'px';
  }

  private lineHeight(): number {
    return this.getProperty('line-height');
  }

  private borderBottomWidth(): number {
    return this.getProperty('border-bottom-width');
  }

  private borderTopWidth(): number {
    return this.getProperty('border-top-width');
  }

  private paddingBottom(): number {
    return this.getProperty('padding-bottom');
  }

  private paddingTop(): number {
    return this.getProperty('padding-top');
  }

  private getProperty(propName: string): number {
    const textarea = this.host.shadowRoot.querySelector('textarea');
    if (!textarea) return;
    return parseInt(document.defaultView.getComputedStyle(textarea, null).getPropertyValue(propName));
  }

  private handleChange = (event) => {
    this.value = event.target.value;
    this.host.dispatchEvent(new window.Event('change'));
    this.groupuiChange.emit();
  };

  private showTypingInfo(): boolean {
    return (this.hasFocus || this.alwaysShowTypingInfo) && this.typingInfoTemplate !== undefined;
  }

  private renderTypingInfo(): string {
    if (!this.maxlength) {
      return this.typingInfoTemplate;
    }
    const length = this.value ? this.value.length : 0;
    return this.typingInfoTemplate
      .replace('{characters-left}', String(this.maxlength - length))
      .replace('{characters-used}', String(length))
      .replace('{characters-max}', String(this.maxlength));
  }

  private isReadonly(): boolean {
    return this.disabled || this.readonly;
  }

  private isLabelSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="label"]');
  }

  private isDescriptionSlotProvided(): boolean {
    return !!this.host.querySelector('[slot="description"]');
  }

  private isAnyInfoVisible(): boolean {
    return (this.isDescriptionSlotProvided() && this.showDescription()) || this.showTypingInfo();
  }

  private useStatusIcon() {
    return this.showStatusIcon && this.severity && this.severity !== 'none';
  }

  private iconSize() {
    return this.size === 's' ? '16' : '24';
  }

  private getStatusIcon() {
    switch (this.severity) {
      case 'warning':
        return `warning-filled-${this.iconSize()}`;
      case 'danger':
        return `error-filled-${this.iconSize()}`;
      case 'success':
        return `success-filled-${this.iconSize()}`;
    }
  }

  private showDescription() {
    if (!this.descriptionOnlyOnFocus) {
      return true;
    } else {
      return this.hasFocus;
    }
  }

  private numberOfRows(): number {
    if (this.rows > this.maxRows) {
      return this.maxRows;
    }
    return this.rows;
  }

  render() {
    const hideScrollbar = this.autoExpand && this.rowCount() === this.fittingRowCount();
    return (
      <Host tabIndex={this.disabled ? -1 : 0}>
        <div>
          {this.isLabelSlotProvided() && (
            <label id="label">
              <slot name="label" />
            </label>
          )}
          <div id="input-wrapper">
            <textarea
              class={{ 'hide-scrollbar': hideScrollbar }}
              placeholder={this.placeholder}
              required={this.required}
              readOnly={this.isReadonly()}
              value={this.value}
              tabIndex={this.disabled ? -1 : 0}
              onInput={this.handleInput}
              onChange={this.handleChange}
              rows={this.numberOfRows()}
              maxLength={this.htmlMaxlengthBehavior ? this.maxlength : undefined}
              autoFocus={this.autofocus}
              aria-labelledby={this.isLabelSlotProvided() ? 'label' : undefined}
              aria-describedby={this.isDescriptionSlotProvided() ? 'description' : undefined}
              {...this.ariaAttributes}
            />
            {this.useStatusIcon() && <groupui-icon name={this.getStatusIcon()} class="status-icon" />}
          </div>
          {this.isAnyInfoVisible() && (
            <div id="info">
              {this.isDescriptionSlotProvided() && this.showDescription() && (
                <div id="description">
                  <slot name="description" />
                </div>
              )}
              {this.showTypingInfo() && <div id="typing-info">{this.renderTypingInfo()}</div>}
            </div>
          )}
        </div>
      </Host>
    );
  }
}
